/* "Trust 55+ only" was a LABEL WITH NOTHING BEHIND IT. Both group-join handlers gated on
   `policy==="approval"` and nothing anywhere read a trust score, so an account at trust 0 joined a
   group whose own chip said it vetted out low-trust accounts. The sibling policy is honest about
   not being wired -- approval toasts "this preview doesn't send it to a moderator yet" -- while
   this one silently let you in, which is the worse of the two failures.
   A UI GUARDRAIL, NOT A SECURITY BOUNDARY: `groups`/`group_members` RLS carries no trust clause,
   so a determined client can still insert the row. What it fixes is the app keeping a promise on
   the screen a climber actually uses, rather than not keeping it at all.
   The threshold lives here because the number was written out three times in three different
   phrasings ("Trust 55+ only", "Trust 55+", "Trust 55+ to join") with nothing tying them together
   or to a check -- exactly the shape that drifts. */
const GROUP_TRUST_MIN=55;
function groupTrustShortfall(cl,me){
  if(!cl||cl.policy!=="trust")return null;
  const mine=vScore(me);
  return mine>=GROUP_TRUST_MIN?null:mine;
}
/* TWO LABELS FOR ONE QUESTION, AND THEY COULD CONTRADICT EACH OTHER. The join-policy chip read
   "Open to all" on a group whose own visibility block, three lines below it, read "Private group ·
   Hidden from search · join by invite only". Both are true of different fields -- `policy` is who
   MAY join, `visibility` is who can FIND it -- but a climber reads one screen, and "anyone can
   join instantly" is not what a private group offers.
   VISIBILITY WINS because it is the half the app actually enforces: the browse list filters
   private groups out for non-members, and `groups` RLS is read-public-or-member. `policy` is
   enforced client-side only (approval, and trust since this change).
   The resolution was written out twice by hand; one spelling now, so a third reader cannot disagree
   with the other two. */
function groupVisOf(cl,groupVis){return (groupVis&&groupVis[cl.id])||(cl&&cl.visibility)||"public";}
function groupJoinLabel(cl,vis,long){
  if(vis==="private")return "Invite only";
  if(cl.policy==="trust")return "Trust "+GROUP_TRUST_MIN+"+"+(long?" to join":"");
  if(cl.policy==="approval")return long?"✓ Organizer approves":"✓ Approval to join";
  return long?"Open to all":"Open";
}
function groupJoinTone(cl,vis){
  if(vis==="private")return C.blue;
  if(!cl.policy||cl.policy==="open")return C.green;
  if(cl.policy==="trust")return C.amber;
  return C.blue;
}
/* LOCATION IS OPTIONAL ON A GROUP — the Create button gates on the name alone — and both surfaces
   built the line as `"📍 Based in "+cl.location+" · N members"`, so a group without one read
   "📍 Based in  · 1 member": a dangling preposition and a double space. It never printed the word
   `undefined`, which is why the guards that scan for that never saw it (`useMyGroups` maps
   `location: g.location || ""`).
   The two writers also disagreed about a blank one. The optimistic local row fell back to
   `ME.location` while `createGroupRow` stored "", so the label said "Based in Bellingham, WA"
   until `myGroupsQ.refetch()` came back and changed it under you. The DB behaviour is the correct
   half: a group is not necessarily based where its creator happens to be, and inventing that is
   the same class of guess as the invented pace next door. Both store what was typed. */
function groupWhere(cl,n){
  const where=(cl&&cl.location||"").trim();
  return "📍 "+(where?"Based in "+where+" · ":"")+n+(n===1?" member":" members");
}
